export type WebhookResult = {
  secret?: string;
  secretShown?: boolean;
  subscription: WebhookSubscription;
};

export type WebhookSubscription = {
  coversFutureProjects?: true;
  createdAt: string;
  eventTypes: Array<"agreement.confirmed" | "delivery.submitted" | "changes.requested" | "acceptance.decided" | "record.changed" | "check.completed" | "check.failed" | "check.pending_human" | "record.evidence_updated">;
  expiresAt: string;
  id: string;
  projectIds: Array<string>;
  renewalRequired?: boolean;
  scope?: "PROJECTS" | "WORKSPACE";
  state: "ACTIVE" | "PAUSED" | "REVOKED";
  target: string;
  workspace?: {
    organizationId: string;
    tenantId: string;
  };
};

export type WebhookTestResult = {
  id: string;
  outcome: "DELIVERED" | "HTTP_FAILURE" | "REDIRECT_BLOCKED" | "TARGET_BLOCKED" | "TRANSPORT_FAILED" | "AUTHORITY_ENDED";
  payload: string;
  sentAt: string;
  status: (number | null);
  subscriptionId: string;
  test: true;
  type: "webhook.test";
};

export type WebhookVerify = {
  rawBody: string;
  signature: string;
  timestamp: string;
};

export type WorkspaceAuditEntry = {
  action: string;
  actor: {
    agentGrantId?: string;
    id: string;
    onBehalfOf?: string;
    type: "PERSON" | "AGENT" | "PLATFORM" | "SYSTEM";
  };
  details: Record<string, unknown>;
  hash: string;
  id: string;
  occurredAt: string;
  origin: {
    kind: "LIVE" | "BACKFILL";
    ref?: string;
    source: string;
  };
  previousHash: string;
  recordedAt: string;
  schema: "prooftask.workspace-audit-entry/v1";
  sequence: number;
  target: {
    id: string;
    type: string;
  };
  workspace: WorkspaceRef;
};

export type WorkspaceAuditHead = ({
  hash: string;
  sequence: number;
} | null);

export type WorkspaceAuditPage = {
  entries: Array<WorkspaceAuditEntry>;
  head: WorkspaceAuditHead;
  next: (number | null);
};

export type WorkspaceAuditVerification = {
  checkedEntries: number;
  head: WorkspaceAuditHead;
  intact: boolean;
  problem: ({
    reason: "HASH_MISMATCH" | "CHAIN_BROKEN" | "SEQUENCE_GAP" | "HEAD_MISMATCH" | "ENTRY_UNREADABLE";
    sequence: number;
  } | null);
  retention: ({
    checkpointHash: string;
    policy: "P1Y";
    prunedAt: string;
    prunedEntries: number;
    prunedThroughSequence: number;
    recordedBefore: string;
  } | null);
  verifiedAt: string;
  workspace: WorkspaceRef;
};

export type WorkspaceRef = {
  organizationId: string;
  tenantId: string;
};
